#!/usr/bin/env node
/* eslint-disable no-console */

const cds = require('@sap/cds')
const { _import, isfile, local, path } = cds.utils

const isCli = require.main === module
const SUPPORTED = ['subscribe', 'unsubscribe', 'upgrade']

// This function must only be changed in a backward compatible way. It is used by DwC.
async function cds_mtx(cmd, tenant, body) {

    const tenants = (Array.isArray(tenant) ? tenant : [tenant]).flatMap(t => t.split(','))
    const one = tenants.length === 1 ? tenants[0] : undefined

    let connectedTenants = []

    try {
        if (!cmd) return _usage()
        if (!SUPPORTED.includes(cmd)) return _usage(`Unknown command ${cmd}.`)
        if (!_hasMtEnv()) return _handleError(`cds-mtx ${cmd} operation can only be run inside a multitenant application environment using @sap/cds-mtxs.`)
        if (!tenants.length) return _handleError(`Please provide a tenant: cds-mtx ${cmd} <tenant>`)
        let parsedMetadata
        if (body) {
            try {
                parsedMetadata = JSON.parse(body)
            } catch (e) {
                return _handleError(`Invalid subscription body: ${e.message}: ${body} `)
            }
        }
        const services = [
            '@sap/cds-mtxs/srv/deployment-service',
            '@sap/cds-mtxs/srv/model-provider',
            '@sap/cds-mtxs/srv/cf/saas-provisioning-service'
        ]
        await _local_server_js()
        cds.emit ('bootstrap')
        const model = await cds.load([...services, '@sap/cds-mtxs/db/extensions'])
        cds.model = cds.compile.for.nodejs(model)
        const d = 'cds.xt.DeploymentService', s = 'cds.xt.SaasProvisioningService'
        const unserved = !cds.services[d]
        const { [d]:ds , [s]:sps } = unserved ? await cds.serve (services) : cds.services
        await cds.plugins

        await cds.emit('served', cds.services)
        if (cmd === 'unsubscribe') {
            await cds.connect.to('db')
        }

        if (tenants.includes('*')) {
            if (cmd !== 'upgrade') return _handleError('"*" only supported for upgrade command')
            if (tenants.length > 1) return _handleError('"*" cannot be combined with other tenants')
            const all = await sps.read('tenant')
            connectedTenants = all.map(t => t.subscribedTenantId)
            await sps.tx({ user: new cds.User.Privileged() }, async (tx) => {
                await tx.upgrade(['*'], parsedMetadata)
            })
            return
        } else if (one === 't0') {
            return
        }
        connectedTenants = tenants

        if (cmd === 'upgrade') {
            await sps.tx({ user: new cds.User.Privileged() }, async (tx) => {
                await tx.upgrade(tenants, parsedMetadata)
            })
        } else {
            for (const t of tenants) await ds[cmd](t, parsedMetadata, parsedMetadata)
        }
    } catch(e) {
        if (isCli) {
            console.error(e.message)
            process.exit(1)
        } else throw e
    } finally {
        if (cds.db) {
            cds.db.disconnect(cds.env.requires.multitenancy.t0 ?? 't0')
            for (const t of connectedTenants) cds.db.disconnect(t)
        }
    }
}

// copied from cds.serve
async function _local_server_js() {
    const _local = file => isfile(file) || isfile (path.join(cds.env.folders.srv,file))
    const cli_js = process.env.CDS_TYPESCRIPT && _local('cli.ts') || _local('cli.js')
    if (cli_js) {
      console.log ('[cds] - loading server from', { file: local(cli_js) })
      await _import(cli_js)
    }
  }

// check for application environment
function _hasMtEnv() {
    if (cds.requires.multitenancy) {
        return true
    }
    for (const service of ['cds.xt.DeploymentService', 'cds.xt.ModelProviderService']) {
        if (!cds.env.requires[service]) {
            console.log(`Service ${service} not configured`)
            return false
        }
    }
    return true
}

async function _handleError(message) {
    if (isCli) {
        console.error(message)
        process.exit(1)
    }
    throw new Error(message)
}

async function _usage(message = '') {
    return _handleError(message + `

USAGE

   cds-mtx <command> <tenant> [--body <json>]
   cds-mtx <command> <tenant1> [<tenant2> ...] [--body <json>]
   cds-mtx <command> <t1,t2,...> [--body <json>]

COMMANDS

   subscribe   subscribe one or more tenants
   unsubscribe unsubscribe one or more tenants
   upgrade     upgrade one or more tenants

EXAMPLES

   cds-mtx subscribe t1
   cds-mtx subscribe t1 t2 t3
   cds-mtx subscribe t1 --body '{ "_": { "hdi": { "create": { "database_id": "<database id>" } } } }'
   cds-mtx unsubscribe t1
   cds-mtx upgrade t1
   cds-mtx upgrade t1 t2 t3
   cds-mtx upgrade t1,t2,t3
   cds-mtx upgrade "*"
`
    )
}

if (isCli) {
    const [, , cmd, ...rest] = process.argv
    const bodyIdx = rest.indexOf('--body')
    const tenants = bodyIdx === -1 ? rest : rest.slice(0, bodyIdx)
    const body = bodyIdx !== -1 ? rest[bodyIdx + 1] : undefined
    if (bodyIdx !== -1 && !body) _usage(`Missing value for --body`)
    ;(async () => await cds_mtx(cmd, tenants, body))()
}
module.exports = { cds_mtx }
